source('mp10_cellchat_high_definition_sensitivity_v1/scripts/common.R')
checks<-list();test<-function(name,value,detail=''){checks[[name]]<<-data.table(check=name,pass=all(value),detail=detail);if(!all(value))stop(name)}
bc<-fromJSON(file.path(baseline,'config/run_config.json'));test('baseline_run_and_annotation_hash',bc$run_id=='c2lfinal_20261108T123140Z_0b5fd64f' & digest(file=file.path(baseline,'tables/analysis_cells.tsv.gz'),algo='sha256')==bc$annotation_sha256 & digest(file=file.path(baseline,'tables/sample_metadata.tsv'),algo='sha256')==bc$sample_sha256)
p<-fread(tb('network_plan.tsv'));d<-fread(tb('specimen_quantiles_coverage.tsv'));e<-fread(tb('epi_full_scores_pools.tsv.gz'));nc<-fread(tb('node_counts.tsv'));b<-fread(file.path(baseline,'tables/network_parts/ALL__fine__sampling.tsv.gz'));ms<-setNames(lapply(p$membership_file,function(f)fread(tb(f))),p$network_id)
test('original_40_specimens_116448_Epi',nrow(d)==40 & nrow(e)==116448);test('strict_specimen_qualification',all(d$C10==(d$n_H05>10 & d$n_L50>10)) & all(d$C30==(d$n_H05>30 & d$n_L50>30)))
for(id in p$network_id){v<-ms[[id]];z<-p[network_id==id];test(paste0(id,':hash'),seqhash(v$barcode)==z$input_hash & seqhash(v[modeled==TRUE,barcode])==z$modeled_hash);test(paste0(id,':unique'),!anyDuplicated(v$barcode));v<-merge(v,e[,.(barcode,L50,H50,H10,H05,priority=random_priority)],by='barcode',all.x=TRUE,sort=FALSE);test(paste0(id,':pool'),all(v[node=='Epi High',get(z$high)]) & all(v[node=='Epi Low',L50]));cnt<-v[node%in%c('Epi High','Epi Low'),.N,by=.(sample_uid,node)];cnt<-dcast(cnt,sample_uid~node,value.var='N');test(paste0(id,':equal_epithelial'),all(cnt[['Epi High']]==cnt[['Epi Low']]));test(paste0(id,':model_boundary'),all(ms[[id]]$modeled==(ms[[id]]$node%in%nc[network_id==id & N>10,node])))
}
for(co in c('C10','C30'))for(sc in unique(p[cohort==co,scope])){
 ids<-p[cohort==co & scope==sc,network_id];lowt<-lapply(ms[ids],function(v)v[node!='Epi High',.(barcode,node)]);test(paste(co,sc,'identical_low_TME_order',sep=':'),identical(lowt[[1]],lowt[[2]])&identical(lowt[[1]],lowt[[3]]));cs<-lapply(ms[ids],function(v)v[,.N,by=node][order(node)]);test(paste(co,sc,'identical_node_counts',sep=':'),identical(cs[[1]],cs[[2]])&identical(cs[[1]],cs[[3]]))
 for(hi in c('H50','H10','H05')){
  v<-ms[[paste(co,sc,hi,sep='__')]];a<-ms[[paste('C10','ALL',hi,sep='__')]];ids2<-d[get(co)==TRUE & (sc=='ALL'|dataset==sc),sample_uid];test(paste(co,sc,hi,'C10_ALL_ordered_subset',sep=':'),identical(v$barcode,a[sample_uid%in%ids2,barcode]));expect<-b[!node%in%c('Epi_MP10_high','Epi_MP10_low') & sample_uid%in%ids2,barcode];test(paste(co,sc,hi,'baseline_TME_order',sep=':'),identical(v[node%in%setdiff(v$node,c('Epi High','Epi Low')),barcode],expect))
 }
}
for(g in c('H50','H10','H05','L50')){v<-copy(e[sample_uid%in%d[C10==TRUE,sample_uid]&get(g)==TRUE]);setorder(v,sample_uid,random_priority,barcode);v[,rk:=seq_len(.N),by=sample_uid];v<-merge(v,d[,.(sample_uid,k_s)],by='sample_uid',sort=FALSE);want<-v[rk<=k_s,barcode];got<-ms[[paste('C10','ALL',if(g=='L50')'H50'else g,sep='__')]][candidate_pool==g,barcode];test(paste0('priority_sampling:',g),setequal(want,got))}
overlap<-rbindlist(lapply(c('H50','H10','H05'),function(h){v<-ms[[paste('C10','ALL',h,sep='__')]][node=='Epi High'];v<-merge(v,e[,.(barcode,H05,MP10_cell)],by='barcode');v[,.(high=h,n_selected=.N,n_in_H05=sum(H05),fraction_in_H05=mean(H05),mean_selected_score=mean(MP10_cell)),by=sample_uid]}));put(overlap,'selected_high_tail_overlap.tsv')
if(!'--initial'%in%commandArgs(TRUE)){
 cfg<-fromJSON(file.path(root,'config/run_config.json'));prov<-fromJSON(file.path(root,'config/domain_provenance.json'));params<-cfg[c('CellChat_version','type','raw.use','population.size','nboot','seed.use','model_nodes')];codehash<-digest(file=file.path(root,'scripts/fast_trimean.cpp'),algo='sha256');st<-fread(tb('network_status.tsv'));test('all_networks_complete_or_documented_NE',all(st$status%in%c('completed','completed_reused','NE')));dom<-fread(tb('fixed_LR_domain.tsv'));ed<-fread(tb('epi_tme_edges.tsv.gz'));ef<-fread(tb('background_adjusted_effects.tsv.gz'));pa<-fread(tb('pathway_background_contributions.tsv.gz'))
 test('effects_unique_keys',!anyDuplicated(ef[,.(cohort,scope,high,min_cells,lr_domain,background_id,direction,target,metric)]));test('all29_targets_per_network',all(ed[,uniqueN(target),by=.(network_id,min_cells,lr_domain,direction)]$V1==29));test('NE_is_NA_never_zero',all(is.na(ed[computed==FALSE,H_W])) & all(is.na(ed[computed==FALSE,H_R])));test('RR_no_pseudocount',all(is.na(ef[L==0,RR])));test('RR_zero_retained',all(ef[H==0 & L>0 & r_B>0 & target_in_background_universe==TRUE,RR]==0))
 for(i in seq_len(nrow(st))){z<-st[i];if(z$status=='NE')next;o<-qread(file.path(root,'objects/networks',paste0(z$network_id,'.qs')),nthreads=1);md<-ms[[z$network_id]][modeled==TRUE];test(paste0(z$network_id,':documented_parameters_provenance'),isTRUE(all.equal(params,o$params)) & isTRUE(all.equal(prov,o$provenance)));key<-digest(list(barcodes=md$barcode,nodes=md$node,params=o$params,provenance=o$provenance,accelerator=codehash),algo='sha256');test(paste0(z$network_id,':resume_key'),identical(key,o$cache_key));test(paste0(z$network_id,':LR_order'),identical(rownames(o$LR),dom$interaction_id) & identical(dimnames(o$prob)[[3]],dom$interaction_id));test(paste0(z$network_id,':raw_zero_P_one'),all(o$pval[o$prob==0]==1));sp<-fread(tb(paste0('lr/',z$network_id,'__raw_sparse.tsv.gz')));test(paste0(z$network_id,':strict_support'),all(sp$supported==(sp$probability>0 & sp$internal_P<.05)));sums<-sp[,.(W=sum(probability[supported]),R=sum(probability),C=sum(supported)),by=.(direction,target,epi_state)];ev<-ed[network_id==z$network_id & min_cells==10 & lr_domain=='fixed_full' & computed==TRUE];for(di in c('output','input'))for(t in ev$target[ev$direction==di])for(state in c('High','Low')){sr<-sums[direction==di & target==t & epi_state==state];a<-ev[direction==di & target==t];val<-if(nrow(sr))c(sr$W,sr$R,sr$C)else c(0,0,0);prefix<-if(state=='High')'H_'else'L_';test(paste(z$network_id,di,t,state,'sparse_aggregate',sep=':'),max(abs(val-as.numeric(a[,paste0(prefix,c('W','R','C')),with=FALSE])))<1e-10)}
 }
 test('pathway_E_additive',all(abs(pa[is.finite(E),.(err=sum(E_path)-E[1]),by=.(network_id,min_cells,lr_domain,background_id,direction,target,metric)]$err)<1e-10))
}
fwrite(rbindlist(checks),file.path(root,'qc/validation_checks.tsv'),sep='\t');cat('VALIDATED',length(checks),'checks\n')
